flags.typeql:
match
$c isa character, has name $name;
$c has centrality $cent;
$c has book1_betweenness_centrality $b1bc;
$c has book1_page_rank $b1pr;
$c has book45_page_rank $b45pr;
let $total = $cent + $b1bc + $b1pr + $b45pr;
sort $total desc;
limit 3;
fetch {
  "characterName": $name,
  "totalCentrality": $total
};

match
$c isa character, has book1_page_rank $b1, has book45_page_rank $b45, has name $name;
let $total = $b1 + $b45;
sort $total desc;
limit 3;
fetch {
  "characterName": $name,
  "totalPageRank": $total
};

match
$c isa character, has book1_page_rank $b1, has book45_page_rank $b45, has pagerank $pr;
let $total = $b1 + $b45 + $pr;
sort $total desc;
limit 5;
fetch {
  "characterName": $c.name,
  "totalPageRank": $total
};

match
$c isa character, has centrality 0.8;
limit 5;
fetch {
  "name": $c.name
};

match
$c isa character, has community 504;
limit 3;
fetch {
  "name": $c.name,
  "community": $c.community
};

match
$c isa character, has community 735;
limit 3;
fetch {
  "name": $c.name,
  "community": $c.community
};

match
$c isa character, has community $comm, has name $n;
$comm == 642;
limit 3;
fetch {
  "name": $n,
  "community": $comm
};

match
$c isa character, has community 579;
limit 5;
fetch {
  "name": $c.name
};
